'use strict';
/* MICRO PULLBACK — QUALITY OPTIMIZER
   Fresh reconstruction of current LIVE strategy. 75% DEV / 25% untouched HOLD.
   Core BUY-only direction, SL=2 ATR, RR=1, maxBars=10 unchanged.
   Optimize entry quality only: hours, EMA separation, impulse, body, close position.
*/
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(p){let a=Array(M.length).fill(NaN),k=2/(p+1),x=M[0].c;for(let i=0;i<M.length;i++){x=i?M[i].c*k+x*(1-k):x;a[i]=x}return a}function atr(p=14){let a=Array(M.length).fill(NaN);for(let i=p;i<M.length;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));a[i]=s/p}return a}const E9=ema(9),E21=ema(21),E50=ema(50),A=atr();
function signals(q){let z=[];for(let i=60;i<M.length-1;i++){let b=M[i],a=A[i],hr=new Date(b.t).getUTCHours();if(hr===20||q.block.includes(hr)||![a,E9[i],E21[i],E50[i],E21[i-3]].every(Number.isFinite)||!(a>0))continue;let rg=b.h-b.l,body=Math.abs(b.c-b.o);if(!(rg>0)||body/rg<q.body)continue;if(Math.abs(E9[i]-E21[i])/a<q.sep)continue;if(!(E9[i]>E21[i]&&E21[i]>E50[i]&&E21[i]>E21[i-3]))continue;let is=i-4,ie=i-2,imp=M[ie].c-M[is].o;if(imp<q.imp*a)continue;let pl=Infinity;for(let j=ie+1;j<i;j++)pl=Math.min(pl,M[j].l);let retr=(M[ie].c-pl)/imp;if(retr<.12||retr>.45)continue;let pos=(b.c-b.l)/rg;if(pos<q.pos||b.c<=M[i-1].h)continue;z.push(i)}return z}
function trades(q){let sig=new Set(signals(q)),out=[],p=null;for(let i=60;i<M.length;i++){if(p){let b=M[i],sl=b.l<=p.sl,tp=b.h>=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c;out.push({t:M[p.si].t,r:(px-p.en)/p.risk,h:new Date(M[p.si].t).getUTCHours()});p=null}if(p)continue}let si=i-1;if(sig.has(si)){let en=M[i].o,risk=2*A[si];p={en,risk,sl:en-risk,tp:en+risk,ei:i,si}}}return out}
function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else{if(x.r<0)gl+=-x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const split=M[Math.floor(M.length*.75)].t,base={block:[],sep:.08,imp:1.3,body:.55,pos:.66},bt=trades(base),bd=bt.filter(x=>x.t<split),bh=bt.filter(x=>x.t>=split),BSD=S(bd),BSH=S(bh);console.log('MICRO PULLBACK — QUALITY OPTIMIZER');console.log('75% DEV / 25% HOLDOUT | SL/RR/maxBars unchanged');console.log('Split',new Date(split).toISOString());console.log('BASE DEV ',F(BSD));console.log('BASE HOLD',F(BSH));console.log('BASE ALL ',F(S(bt)),'\n');
const blocks=[[],[16],[17],[16,17],[13,16,17],[15,16,17],[13,15,16,17],[7,13,16,17],[13,16,17,19]],seps=[.08,.10,.12,.15,.18],imps=[1.3,1.4,1.5,1.65],bodies=[.55,.60,.65,.70],poss=[.66,.70,.74,.78];let rows=[],id=0;for(const block of blocks)for(const sep of seps)for(const imp of imps)for(const body of bodies)for(const pos of poss){id++;let q={block,sep,imp,body,pos},t=trades(q),d=t.filter(x=>x.t<split),h=t.filter(x=>x.t>=split),sd=S(d),sh=S(h);if(sd.n<130||sh.n<35||sd.n<BSD.n*.50)continue;let score=(sd.pf-BSD.pf)*2+(sd.wr-BSD.wr)/20+(BSD.dd-sd.dd)/5;rows.push({id,q,sd,sh,score})}rows.sort((a,b)=>b.score-a.score);function line(x){let q=x.q;return `#${x.id} block[${q.block.join(',')||'-'}] SEP>=${q.sep} IMP>=${q.imp} BODY>=${q.body} POS>=${q.pos} | DEV ${F(x.sd)} | HOLD ${F(x.sh)}`}
console.log('🏆 TOP 20 — DEV RANKING; HOLD NEVER RANKED');rows.slice(0,20).forEach(x=>console.log(line(x)));let robust=rows.filter(x=>x.sh.pf>=BSH.pf&&x.sh.wr>=BSH.wr&&x.sh.dd<=BSH.dd*1.10&&x.sd.pf>BSD.pf&&x.sd.wr>=BSD.wr);console.log('\n🛡️ ROBUST SHORTLIST');if(!robust.length)console.log('NONE — do not change live from this search.');else robust.slice(0,20).forEach(x=>console.log(line(x)));